(function(){'use strict';
/* Public Census Records Database generator — jahdb-census-records-public-generator-1.0.
   Property of Justin Addam Higgins (JAH).
   Deterministic: same seed always makes the same record.
   src:"public" = real public aggregate census statistics */
function pad(n){var s=String(n);while(s.length<6)s='0'+s;return s;}
var PREFIX='JAH-CENPUB-';
var SRC='public';
var RECORD_KIND='public census record';
var GENRES=["population total", "historical census", "demographic breakdown", "urbanization", "migration", "methodology"];
var TOPICS=[{"title": "World population reaches 8 billion (UN, 2022)", "brief": "On 15 November 2022 the United Nations marked the Day of Eight Billion: the world population reached 8,000,000,000. The milestone reflects falling mortality and rising life expectancy; growth is now concentrated in sub-Saharan Africa and South Asia.", "genre": "population total", "text": "MILESTONE RECORD — WORLD POPULATION\nSource: United Nations, World Population Prospects 2022 (public aggregate statistics).\n\nThe United Nations Population Division designated 15 November 2022 as the Day of Eight Billion, the date the world population reached 8,000,000,000 people.\n\nKey aggregates (UN WPP 2022, medium variant):\n- World population, 2022: 8.0 billion\n- Annual growth rate, 2022: under 1% per year for the first time since 1950\n- More than half of projected growth to 2050: eight countries — DR Congo, Egypt, Ethiopia, India, Nigeria, Pakistan, Philippines, Tanzania\n- Sub-Saharan Africa's share of world population: projected to approach 35% by 2100\n\nHistorical milestones: 1 billion c.1800; 2 billion 1927; 3 billion 1960; 4 billion 1974; 5 billion 11 July 1987; 6 billion 12 Oct 1999; 7 billion 31 Oct 2011; 8 billion 15 Nov 2022.\n\nThis record contains aggregate statistics only. No individual personal data is collected or stored in this database.", "facts": ["World population 2022: 8.0 billion (UN WPP 2022).", "Day of Eight Billion: 15 November 2022.", "Growth now under 1% per year."]}, {"title": "China — Seventh National Census, 2020", "brief": "China's 2020 census counted 1,411,780,000 people on the mainland, an increase of 72 million over 2010 — the slowest decade of growth in the census series, with urbanization passing 60%.", "genre": "population total", "text": "NATIONAL CENSUS RECORD — PEOPLE'S REPUBLIC OF CHINA, 2020\nSource: National Bureau of Statistics of China, Seventh National Population Census (public aggregate statistics).\n\nMainland population: 1,411,780,000 (1 November 2020 reference date).\n\nHeadline aggregates:\n- Increase over 2010: +72,060,000 (+5.38%)\n- Urbanization rate: 63.89% (up from 49.68% in 2010)\n- Male: 51.24% / Female: 48.76%\n- Aged 60 and over: 18.70%\n- Average household size: 2.62 persons\n- Han ethnicity: 91.11%\n\nContext: the slowest ten-year growth since the census series began in 1953, reflecting sustained low fertility. China remained the world's most populous country at the census date.\n\nThis record contains aggregate statistics only.", "facts": ["Mainland population 2020: 1,411,780,000.", "Urbanization: 63.89%.", "Slowest decade of growth in the series."]}, {"title": "India — Census 2011", "brief": "India's 2011 census recorded 1,210,854,977 people, making it the second most populous country. Uttar Pradesh alone counted nearly 200 million — more than most nations.", "genre": "population total", "text": "NATIONAL CENSUS RECORD — INDIA, 2011\nSource: Office of the Registrar General & Census Commissioner, India (public aggregate statistics).\n\nTotal population: 1,210,854,977 (1 March 2011).\n\nHeadline aggregates:\n- Males: 623,270,000 / Females: 587,580,000\n- Decadal growth 2001–2011: 17.7% (down from 21.5%)\n- Literacy rate (age 7+): 74.04%\n- Urban population: 31.16%\n- Largest state: Uttar Pradesh, 199,812,341\n- Smallest state/UT populations include Lakshadweep at 64,473\n\nIndia's census is among the largest administrative exercises in the world, enumerating over 1.2 billion people across 640 districts.\n\nThis record contains aggregate statistics only.", "facts": ["Population 2011: 1,210,854,977.", "Decadal growth: 17.7%.", "Literacy (7+): 74.04%."]}, {"title": "United States — 2020 Census", "brief": "The 2020 US census counted 331,449,281 residents, a 7.4% increase since 2010 — the second-slowest decade of growth in US history. California remained the most populous state.", "genre": "population total", "text": "NATIONAL CENSUS RECORD — UNITED STATES, 2020\nSource: US Census Bureau, 2020 Census (public aggregate statistics).\n\nResident population: 331,449,281 (1 April 2020).\n\nHeadline aggregates:\n- Growth 2010–2020: +7.4% (second-slowest decade on record)\n- Most populous state: California, 39,538,223\n- Least populous state: Wyoming, 576,851\n- Fastest-growing state: Utah (+18.4%)\n- Metropolitan areas: 86% of the population lived in metro areas\n\nThe 2020 census was the first US census to invite online response nationwide.\n\nThis record contains aggregate statistics only.", "facts": ["Resident population 2020: 331,449,281.", "Decadal growth: 7.4%.", "California: 39,538,223."]}, {"title": "Indonesia — 2020 Census", "brief": "Indonesia's 2020 census recorded 270,203,917 people across its archipelago, with Java holding 56% of the population on 7% of the land.", "genre": "population total", "text": "NATIONAL CENSUS RECORD — INDONESIA, 2020\nSource: Statistics Indonesia (BPS), 2020 Population Census (public aggregate statistics).\n\nTotal population: 270,203,917 (September 2020).\n\nHeadline aggregates:\n- Males: 136,661,899 / Females: 133,542,018\n- Java's share: 56.10% of population on ~7% of land area\n- Largest province: West Java, 48,274,162\n- Annual growth rate 2010–2020: 1.25%\n\nIndonesia is the world's fourth most populous country and the largest archipelagic state.\n\nThis record contains aggregate statistics only.", "facts": ["Population 2020: 270,203,917.", "Java holds 56.1% of people.", "Growth rate: 1.25% per year."]}, {"title": "Brazil — 2022 Census", "brief": "Brazil's 2022 census counted 203,080,756 people. São Paulo state alone held 44.4 million; the Southeast region held 41.8% of Brazilians.", "genre": "population total", "text": "NATIONAL CENSUS RECORD — BRAZIL, 2022\nSource: IBGE, 2022 Demographic Census (public aggregate statistics).\n\nTotal population: 203,080,756 (1 August 2022).\n\nHeadline aggregates:\n- Growth 2010–2022: +6.5% (slowest since 1872 series began)\n- Southeast region: 41.8% of population\n- São Paulo state: 44,411,238 (most populous)\n- Roraima: 636,707 (least populous state)\n\nBrazil is the most populous country in Latin America and the Portuguese-speaking world.\n\nThis record contains aggregate statistics only.", "facts": ["Population 2022: 203,080,756.", "Slowest growth since 1872.", "São Paulo state: 44.4M."]}, {"title": "Pakistan — 2023 Digital Census", "brief": "Pakistan's 2023 digital census — South Asia's first fully digital count — recorded 241,499,431 people, with Punjab holding over half the population.", "genre": "population total", "text": "NATIONAL CENSUS RECORD — PAKISTAN, 2023\nSource: Pakistan Bureau of Statistics, 7th Population & Housing Census (public aggregate statistics).\n\nTotal population: 241,499,431.\n\nHeadline aggregates:\n- Punjab: 127,688,922 (52.9%)\n- Sindh: 55,696,147\n- Khyber Pakhtunkhwa: 40,856,097\n- Balochistan: 14,894,402\n- Annual growth rate: 2.55%\n\nPakistan conducted South Asia's first fully digital census in 2023.\n\nThis record contains aggregate statistics only.", "facts": ["Population 2023: 241,499,431.", "Punjab: 52.9% of total.", "Growth rate: 2.55% per year."]}, {"title": "Nigeria — 2006 Census and UN estimates", "brief": "Nigeria's last full census (2006) counted 140,431,790. UN estimates place 2023 population near 223.8 million, making Nigeria Africa's most populous nation.", "genre": "population total", "text": "NATIONAL CENSUS RECORD — NIGERIA\nSource: National Population Commission 2006 census; UN WPP 2022 estimates (public aggregate statistics).\n\n2006 census total: 140,431,790.\nUN estimate, 2023: ~223,800,000.\n\nHeadline aggregates (2006):\n- Kano state: 9,401,288 (most populous)\n- Lagos state: 9,113,605\n- Annual growth rate: 3.2% (among the world's highest)\n\nNigeria is Africa's most populous country; the UN projects it will become the world's third most populous country around 2050.\n\nThis record contains aggregate statistics only.", "facts": ["2006 census: 140,431,790.", "2023 UN estimate: ~223.8M.", "Growth: 3.2% per year."]}, {"title": "Bangladesh — 2022 Census", "brief": "Bangladesh's 2022 census recorded 169,828,911 people — one of the world's densest large populations, at over 1,100 people per square kilometre.", "genre": "population total", "text": "NATIONAL CENSUS RECORD — BANGLADESH, 2022\nSource: Bangladesh Bureau of Statistics, 2022 Population & Housing Census (public aggregate statistics).\n\nTotal population: 169,828,911 (15 June 2022).\n\nHeadline aggregates:\n- Population density: ~1,119 per sq km (among the world's highest for large countries)\n- Dhaka division: 44,215,107 (most populous)\n- Literacy (7+): 74.66%\n- Annual growth rate: 1.22%\n\nThis record contains aggregate statistics only.", "facts": ["Population 2022: 169,828,911.", "Density: ~1,119 per sq km.", "Literacy: 74.66%."]}, {"title": "Mexico — 2020 Census", "brief": "Mexico's 2020 census counted 126,014,024 people. The State of Mexico and Mexico City together held over a fifth of the nation.", "genre": "population total", "text": "NATIONAL CENSUS RECORD — MEXICO, 2020\nSource: INEGI, 2020 Population and Housing Census (public aggregate statistics).\n\nTotal population: 126,014,024 (15 March 2020).\n\nHeadline aggregates:\n- Growth 2010–2020: +12.2%\n- State of Mexico: 16,992,418 (most populous)\n- Mexico City: 9,209,944\n- Median age: 29 years\n\nMexico is the most populous Spanish-speaking country in the world.\n\nThis record contains aggregate statistics only.", "facts": ["Population 2020: 126,014,024.", "Growth 2010–2020: 12.2%.", "Median age: 29."]}, {"title": "The first US census, 1790", "brief": "The 1790 United States census counted 3,893,635 people — the first modern census conducted under constitutional authority, taken by US Marshals on horseback.", "genre": "historical census", "text": "HISTORICAL CENSUS RECORD — UNITED STATES, 1790\nSource: US Census Bureau historical series (public aggregate statistics).\n\nTotal population: 3,893,635 (first Monday of August 1790).\n\nHeadline aggregates:\n- Free white males 16+: 813,365\n- Free white males under 16: 802,127\n- Free white females: 1,541,263\n- All other free persons: 59,152\n- Enslaved persons: 697,681\n- Most populous state: Virginia, 747,610\n\nConducted under Article I, Section 2 of the Constitution for apportioning House seats. Cost: $44,377. The schedules survive for most states; Delaware, Georgia, Kentucky, New Jersey, Tennessee, and Virginia schedules are lost.\n\nThis record contains aggregate statistics only.", "facts": ["Total 1790: 3,893,635.", "Purpose: House apportionment.", "Cost: $44,377."]}, {"title": "The 1801 Census of England and Wales", "brief": "Britain's first census (1801) counted 8,872,980 people in England and Wales, organized by the statistician John Rickman amid Napoleonic-war anxieties about food supply.", "genre": "historical census", "text": "HISTORICAL CENSUS RECORD — ENGLAND AND WALES, 1801\nSource: UK Parliamentary Papers / Histpop (public aggregate statistics).\n\nTotal population: 8,872,980 (10 March 1801).\n\nHeadline aggregates:\n- Families chiefly in agriculture: 896,082\n- Families in trade/manufacture: 1,345,000+\n- London: ~1,000,000 (already Europe's largest city)\n- Organizer: John Rickman, clerk to the House of Commons\n\nThe 1801 census asked only six questions via parish overseers. Scotland counted separately (1,608,420). No individual schedules survive — only parish aggregates.\n\nThis record contains aggregate statistics only.", "facts": ["Total 1801: 8,872,980.", "Organizer: John Rickman.", "Only parish aggregates survive."]}, {"title": "Domesday Book, 1086 — England's great survey", "brief": "William the Conqueror's Domesday survey of 1086 recorded landholders, ploughs, and livestock across England — the closest thing to a census for 900 years. Historians estimate 1.5–2.5 million people.", "genre": "historical census", "text": "HISTORICAL CENSUS RECORD — ENGLAND, 1086\nSource: The National Archives, Domesday Book (public historical record).\n\nThe Domesday survey recorded, settlement by settlement: landholders, hides of land, plough teams, mills, and heads of livestock. Population estimates derived from it: 1.5–2.5 million.\n\nHeadline aggregates:\n- Settlements recorded: ~13,418\n- Tenants-in-chief: ~1,400\n- Recorded population (household heads): ~268,000\n- Estimated total population: 1.5–2.5 million\n\nIt omits London, Winchester, and the far north. The survey's purpose was fiscal: establishing what the King could tax.\n\nThis record contains aggregate statistics only.", "facts": ["Survey year: 1086.", "Settlements: ~13,418.", "Estimated population: 1.5–2.5M."]}, {"title": "Han dynasty census, 2 CE — 57.7 million", "brief": "China's Han dynasty census of 2 CE recorded 12,366,470 households and 57,671,400 individuals — the earliest large-scale census with surviving figures.", "genre": "historical census", "text": "HISTORICAL CENSUS RECORD — HAN CHINA, 2 CE\nSource: Book of Han (Hanshu), Geography treatise (public historical record).\n\nRecorded: 12,366,470 households; 57,671,400 individuals.\n\nThis is the earliest census in world history with detailed surviving figures, conducted for taxation and corvée labor administration. The figures imply sophisticated household registration (hukou's ancient ancestor).\n\nFor comparison, the Roman Empire at the same period is estimated at 45–60 million — the Han census suggests China alone matched or exceeded it.\n\nThis record contains aggregate statistics only.", "facts": ["Households: 12,366,470.", "Individuals: 57,671,400.", "Earliest detailed census figures."]}, {"title": "US Census 1900 — 76.2 million", "brief": "The 1900 US census counted 76,212,168 people and was the last processed entirely by hand-punched Hollerith tabulating machines — the technology that became IBM.", "genre": "historical census", "text": "HISTORICAL CENSUS RECORD — UNITED STATES, 1900\nSource: US Census Bureau historical series (public aggregate statistics).\n\nTotal population: 76,212,168 (1 June 1900).\n\nHeadline aggregates:\n- Growth 1890–1900: +21.0%\n- Urban population: 39.6%\n- Foreign-born: 13.6%\n- Most populous state: New York, 7,268,894\n\nProcessing used Herman Hollerith's punched-card tabulators — the contract that founded the Computing-Tabulating-Recording Company, later IBM.\n\nThis record contains aggregate statistics only.", "facts": ["Total 1900: 76,212,168.", "Urban: 39.6%.", "Hollerith tabulators used."]}, {"title": "World population milestones, 1800–2011", "brief": "From 1 billion around 1800 to 7 billion on 31 October 2011: the UN's Day of Seven Billion marked a doubling in just 50 years.", "genre": "historical census", "text": "HISTORICAL MILESTONE RECORD — WORLD POPULATION\nSource: United Nations Population Division (public aggregate statistics).\n\n- c.1800: 1 billion\n- 1927: 2 billion (127 years)\n- 1960: 3 billion (33 years)\n- 1974: 4 billion (14 years)\n- 11 July 1987: 5 billion — Day of Five Billion\n- 12 October 1999: 6 billion — Day of Six Billion\n- 31 October 2011: 7 billion — Day of Seven Billion\n\nThe interval between billions shrank dramatically with 20th-century mortality decline, then began lengthening again as fertility fell worldwide.\n\nThis record contains aggregate statistics only.", "facts": ["1B c.1800; 7B on 31 Oct 2011.", "Fastest doubling: 1960–1999.", "Growth rate peaked in the 1960s."]}, {"title": "Roman censuses — citizens counted for tax and legions", "brief": "Rome's Republican censuses counted adult male citizens for military levy and taxation. The census of 28 BCE under Augustus recorded 4,063,000 citizens.", "genre": "historical census", "text": "HISTORICAL CENSUS RECORD — ROME\nSource: Res Gestae Divi Augusti; Livy (public historical record).\n\nAugustus's census of 28 BCE: 4,063,000 Roman citizens. Later Augustan censuses: 8 CE: 4,233,000; 14 CE: 4,937,000.\n\nThe Republican census (held roughly every five years by the censors) registered adult male citizens, their property class, and their tribe — determining legion service and voting century. The word 'census' itself comes from the Latin 'censere', to assess.\n\nTotal imperial population is estimated at 45–60 million; the citizen counts cover only a fraction.\n\nThis record contains aggregate statistics only.", "facts": ["28 BCE: 4,063,000 citizens.", "Purpose: levy and taxation.", "'Census' from Latin censere."]}, {"title": "The 1881 Census of England and Wales — first fully searchable", "brief": "The 1881 census counted 25,974,439 people in England and Wales and became the first British census fully transcribed and searchable by name — a landmark for public genealogy.", "genre": "historical census", "text": "HISTORICAL CENSUS RECORD — ENGLAND AND WALES, 1881\nSource: The National Archives (public aggregate statistics).\n\nTotal population: 25,974,439 (3 April 1881).\n\nHeadline aggregates:\n- Growth 1871–1881: +14.4%\n- London: 3,830,297\n- Urban share: ~70%\n\nThe 1881 census was transcribed in full by the Church of Jesus Christ of Latter-day Saints and partners, making it the first Victorian census searchable person-by-person — the foundation stone of modern family history research.\n\nThis record contains aggregate statistics only.", "facts": ["Total 1881: 25,974,439.", "London: 3,830,297.", "First fully transcribed Victorian census."]}, {"title": "Brazil's first census, 1872", "brief": "Brazil's 1872 census — the first in Latin America — counted 9,930,478 people, including 1,510,806 enslaved persons, sixteen years before abolition.", "genre": "historical census", "text": "HISTORICAL CENSUS RECORD — BRAZIL, 1872\nSource: IBGE historical series (public aggregate statistics).\n\nTotal population: 9,930,478 (1 August 1872).\n\nHeadline aggregates:\n- Enslaved persons: 1,510,806 (15.2%)\n- Free population: 8,419,672\n- Most populous province: Minas Gerais, 2,039,735\n\nThe first census conducted in Latin America, ordered by the imperial government of Dom Pedro II.\n\nThis record contains aggregate statistics only.", "facts": ["Total 1872: 9,930,478.", "Enslaved: 15.2%.", "First census in Latin America."]}, {"title": "Japan's first modern census, 1920", "brief": "Japan's 1920 census — Asia's first modern census — counted 55,963,053 people in Japan proper, run by the new Statistics Bureau.", "genre": "historical census", "text": "HISTORICAL CENSUS RECORD — JAPAN, 1920\nSource: Statistics Bureau of Japan (public aggregate statistics).\n\nTotal population (Japan proper): 55,963,053 (1 October 1920).\n\nHeadline aggregates:\n- Households: 11,300,000+\n- Tokyo prefecture: 3,699,428\n- Urbanization: ~18%\n\nJapan's 1920 census was the first modern census in Asia, modeled partly on Western practice and conducted every five years since (every ten for the full 'large-scale' cycle).\n\nThis record contains aggregate statistics only.", "facts": ["Total 1920: 55,963,053.", "First modern census in Asia.", "Tokyo: 3,699,428."]}, {"title": "Median age around the world, 2020", "brief": "The world's median age was 30.4 in 2020 — but the spread is enormous: 15.1 in Uganda, 48.4 in Japan. This record maps the age divide.", "genre": "demographic breakdown", "text": "DEMOGRAPHIC ANALYSIS — MEDIAN AGE BY COUNTRY, 2020\nSource: UN World Population Prospects 2022 (public aggregate statistics).\n\nWorld median age: 30.4 years.\n\nOldest populations (median age):\n- Japan: 48.4\n- Italy: 47.3\n- Germany: 45.7\n- Portugal: 46.2\n\nYoungest populations:\n- Uganda: 15.1\n- Chad: 15.4\n- Mali: 15.5\n- DR Congo: 16.0\n\nThe gap between Japan and Uganda — 33 years — summarizes the demographic divide: aging rich countries versus youthful poor ones. By 2050 the world median age is projected at 36.\n\nThis record contains aggregate statistics only.", "facts": ["World median age 2020: 30.4.", "Japan 48.4 vs Uganda 15.1.", "2050 projection: 36."]}, {"title": "Global fertility: 2.3 children per woman, 2021", "brief": "World total fertility fell to 2.3 in 2021 — just above replacement. South Korea (0.81) and Niger (6.7) mark the extremes.", "genre": "demographic breakdown", "text": "DEMOGRAPHIC ANALYSIS — TOTAL FERTILITY RATE, 2021\nSource: UN World Population Prospects 2022 (public aggregate statistics).\n\nWorld TFR: 2.3 children per woman.\n\nLowest fertility:\n- South Korea: 0.81 (2021)\n- Singapore: 1.02\n- China: 1.16 (2020 census)\n\nHighest fertility:\n- Niger: 6.7\n- Chad: 6.2\n- DR Congo: 6.0\n\nTwo-thirds of humanity now lives in countries below replacement fertility (2.1). The UN projects world fertility at 2.1 by 2050.\n\nThis record contains aggregate statistics only.", "facts": ["World TFR 2021: 2.3.", "South Korea: 0.81; Niger: 6.7.", "Two-thirds below replacement."]}, {"title": "Life expectancy worldwide, 2019", "brief": "Global life expectancy reached 72.8 years in 2019 before the pandemic. Japan (84.6) and the Central African Republic (53.9) span a 30-year gap.", "genre": "demographic breakdown", "text": "DEMOGRAPHIC ANALYSIS — LIFE EXPECTANCY AT BIRTH, 2019\nSource: UN World Population Prospects 2022 (public aggregate statistics).\n\nWorld: 72.8 years (70.8 male, 75.0 female).\n\nHighest:\n- Japan: 84.6\n- Switzerland: 84.2\n- Singapore: 84.0\n\nLowest:\n- Central African Republic: 53.9\n- Chad: 55.1\n- Nigeria: 55.4\n\nCOVID-19 cut global life expectancy by about 1.7 years in 2020–2021 — the first sustained global decline since the 1918 influenza.\n\nThis record contains aggregate statistics only.", "facts": ["World 2019: 72.8 years.", "Japan 84.6 vs CAR 53.9.", "COVID cut ~1.7 years."]}, {"title": "The world speaks: largest mother tongues, 2023 estimates", "brief": "Mandarin (~940M native speakers), Spanish (~485M), and English (~380M native, 1.5B total) top the world language table — census language questions make this measurable.", "genre": "demographic breakdown", "text": "DEMOGRAPHIC ANALYSIS — LANGUAGES BY NATIVE SPEAKERS\nSource: Ethnologue 2023; national census language questions (public aggregate statistics).\n\nNative speakers (approximate):\n- Mandarin Chinese: ~940 million\n- Spanish: ~485 million\n- English: ~380 million (1.5 billion total speakers)\n- Hindi: ~345 million\n- Portuguese: ~230 million\n- Bengali: ~230 million\n- Russian: ~150 million\n- Japanese: ~125 million\n\nCensus language questions (as in India's census, Canada's, Switzerland's) are the primary source for mother-tongue statistics worldwide.\n\nThis record contains aggregate statistics only.", "facts": ["Mandarin: ~940M native.", "English: 1.5B total speakers.", "Censuses are the main source."]}, {"title": "Religion counts: the 2011 India census religion table", "brief": "India's 2011 census religion table: Hindu 79.8%, Muslim 14.2%, Christian 2.3%, Sikh 1.7% — the world's largest religion count.", "genre": "demographic breakdown", "text": "DEMOGRAPHIC ANALYSIS — RELIGION, INDIA 2011\nSource: Census of India 2011, religion tables (public aggregate statistics).\n\n- Hindu: 966,257,353 (79.8%)\n- Muslim: 172,245,158 (14.2%)\n- Christian: 27,819,588 (2.3%)\n- Sikh: 20,833,116 (1.7%)\n- Buddhist: 8,442,972 (0.7%)\n- Jain: 4,451,753 (0.4%)\n\nIndia's Muslim population alone (172M) exceeds the total population of all but a handful of countries. Religion has been asked in every Indian census since 1872.\n\nThis record contains aggregate statistics only.", "facts": ["Hindu 79.8%; Muslim 14.2%.", "Asked since 1872.", "Largest religion count on Earth."]}, {"title": "US 2020: the multiracial count triples", "brief": "The 2020 US census recorded 33.8 million multiracial Americans — up from 9 million in 2010 — the decade's biggest demographic story.", "genre": "demographic breakdown", "text": "DEMOGRAPHIC ANALYSIS — RACE, UNITED STATES 2020\nSource: US Census Bureau 2020 (public aggregate statistics).\n\n- Two or more races: 33,848,943 (10.2%), up from 2.9% in 2010\n- White alone: 57.8% (non-Hispanic)\n- Hispanic or Latino: 62,080,044 (18.7%)\n- Black alone: 12.1%\n- Asian alone: 5.9%\n\nThe jump reflects both real change and improved question design capturing multiracial identity. California (15.3M) and Texas (11.4M) hold the largest Hispanic populations.\n\nThis record contains aggregate statistics only.", "facts": ["Multiracial: 33.8M (10.2%).", "Hispanic: 62.1M (18.7%).", "Question design improved capture."]}, {"title": "China 2020: 18.7% aged 60 and over", "brief": "China's 2020 census found 264 million people aged 60+ (18.7%) — the demographic weight behind the world's fastest aging transition.", "genre": "demographic breakdown", "text": "DEMOGRAPHIC ANALYSIS — AGING, CHINA 2020\nSource: National Bureau of Statistics of China (public aggregate statistics).\n\n- Aged 60+: 264,018,766 (18.70%)\n- Aged 65+: 190,635,280 (13.50%)\n- Children 0–14: 17.95%\n- Working age 15–59: 63.35%\n\nIn 1990 only 8.6% of China was 60+. The one-child era's small cohorts are now entering old age while the 1960s baby boomers retire — the dependency ratio is turning fast.\n\nThis record contains aggregate statistics only.", "facts": ["60+: 264M (18.7%).", "Up from 8.6% in 1990.", "Dependency ratio turning."]}, {"title": "Africa's youth bulge: 60% under 25", "brief": "Africa's median age is 19.7 — the world's youngest continent. 60% of Africans are under 25, a youth bulge with enormous economic stakes.", "genre": "demographic breakdown", "text": "DEMOGRAPHIC ANALYSIS — AGE STRUCTURE, AFRICA\nSource: UN World Population Prospects 2022 (public aggregate statistics).\n\n- Africa median age: 19.7 years (world: 30.4)\n- Under 25: ~60% of population\n- Under 15: ~40%\n- Fertility: 4.4 children per woman (2021)\n\nBy 2050, one in three of the world's young people will be African. Whether the youth bulge becomes a dividend or a strain depends on schooling and jobs.\n\nThis record contains aggregate statistics only.", "facts": ["Median age: 19.7.", "60% under 25.", "1 in 3 young people by 2050."]}, {"title": "Households are shrinking worldwide", "brief": "Average household size fell almost everywhere: China 2.62 (2020), US 2.6, India 4.4 (2011), EU 2.3. Solo living is the fastest-growing household type.", "genre": "demographic breakdown", "text": "DEMOGRAPHIC ANALYSIS — HOUSEHOLD SIZE\nSource: National censuses 2010–2022 rounds (public aggregate statistics).\n\nAverage household size:\n- China (2020): 2.62 (down from 3.96 in 1982)\n- United States (2020): 2.6\n- India (2011): 4.4\n- European Union (2022): 2.3\n- Japan (2020): 2.21\n\nOne-person households: ~15% in the US, ~38% in the EU, ~16% in China (2020) — rising everywhere as populations age and urbanize.\n\nThis record contains aggregate statistics only.", "facts": ["China: 2.62; EU: 2.3.", "Solo living rising everywhere.", "Driven by aging + urbanization."]}, {"title": "Sex ratios: from Qatar (2.9) to Latvia (0.85)", "brief": "The world has 101.7 men per 100 women — but migration skews Qatar to 2.9 while longevity skews Latvia to 0.85.", "genre": "demographic breakdown", "text": "DEMOGRAPHIC ANALYSIS — SEX RATIO\nSource: UN World Population Prospects 2022 (public aggregate statistics).\n\nWorld: 101.7 males per 100 females.\n\nHighest (male-skewed, migrant labor):\n- Qatar: ~2.9\n- UAE: ~2.2\n- Oman: ~1.9\n\nLowest (female-skewed, longevity + history):\n- Latvia: 0.85\n- Lithuania: 0.86\n- Ukraine: 0.87\n\nNatural birth ratio is ~1.05; deviations reflect migration, war mortality, and longevity gaps.\n\nThis record contains aggregate statistics only.", "facts": ["World: 101.7 per 100.", "Qatar ~2.9; Latvia 0.85.", "Migration and longevity drive skew."]}, {"title": "Tokyo — the world's largest metro, ~37 million", "brief": "Greater Tokyo's ~37 million people make it the largest metropolitan economy on Earth — bigger than most countries, counted across four prefectures.", "genre": "urbanization", "text": "URBAN ANALYSIS — TOKYO METROPOLITAN AREA\nSource: UN World Urbanization Prospects 2018; Statistics Bureau of Japan (public aggregate statistics).\n\n- Greater Tokyo population: ~37,000,000\n- Prefectures: Tokyo, Kanagawa, Saitama, Chiba\n- Share of Japan's population: ~29%\n- Rail ridership: Shinjuku station alone handles ~3.6M passengers daily\n\nTokyo has been the world's largest city since passing Mexico City in the 1960s. Its rail network carries more people daily than most national railways.\n\nThis record contains aggregate statistics only.", "facts": ["Metro: ~37M.", "29% of Japan.", "World's largest since the 1960s."]}, {"title": "Delhi passes 32 million", "brief": "The UN estimates Delhi's urban agglomeration near 32 million — set to become the world's largest city by around 2028.", "genre": "urbanization", "text": "URBAN ANALYSIS — DELHI\nSource: UN World Urbanization Prospects 2018 (public aggregate statistics).\n\n- Urban agglomeration: ~32,000,000\n- Census 2011 (NCT): 16,787,941\n- Projected: world's largest city c.2028\n\nDelhi's growth (from 1.7M in 1951) tracks India's urbanization surge: the urban share rose from 17% in 1951 to 35%+ today.\n\nThis record contains aggregate statistics only.", "facts": ["Agglomeration: ~32M.", "World's largest c.2028.", "From 1.7M in 1951."]}, {"title": "Shanghai — 28 million in one municipality", "brief": "Shanghai municipality counted 24.9 million in the 2020 census within its borders; the metro exceeds 28 million — China's largest city.", "genre": "urbanization", "text": "URBAN ANALYSIS — SHANGHAI\nSource: China 2020 census; UN WUP 2018 (public aggregate statistics).\n\n- Municipality (2020 census): 24,870,000\n- Metro agglomeration: ~28,000,000\n- Growth 2010–2020: +8.2%\n- Pudong district alone: 5.68M\n\nShanghai's metro carries the world's longest subway system by route length (~800 km).\n\nThis record contains aggregate statistics only.", "facts": ["Municipality: 24.87M.", "Metro: ~28M.", "World's longest subway."]}, {"title": "56% of humanity is urban, 2021", "brief": "The UN put the urban share at 56% in 2021 — up from 30% in 1950, heading for 68% by 2050. The urban millennium arrived in 2007.", "genre": "urbanization", "text": "URBAN ANALYSIS — WORLD URBANIZATION\nSource: UN World Urbanization Prospects 2018 (public aggregate statistics).\n\n- Urban share 1950: 30%\n- Urban share 2007: 50% (the crossover year)\n- Urban share 2021: 56%\n- Projected 2050: 68%\n\nRegional urban shares (2021): North America 83%, Latin America 81%, Europe 75%, Asia 52%, Africa 44%.\n\nNearly all future urban growth will be in Asia and Africa.\n\nThis record contains aggregate statistics only.", "facts": ["56% urban in 2021.", "68% projected by 2050.", "Growth concentrated in Asia/Africa."]}, {"title": "China's urbanization: 63.9% in 2020", "brief": "China's 2020 census found 63.89% urban — up from 17.9% in 1978. Over 900 million Chinese now live in cities.", "genre": "urbanization", "text": "URBAN ANALYSIS — CHINA\nSource: National Bureau of Statistics of China (public aggregate statistics).\n\n- Urban share 1978: 17.9%\n- Urban share 2000: 36.2%\n- Urban share 2010: 49.7%\n- Urban share 2020: 63.89% (~902 million people)\n\nThe largest rural-to-urban migration in human history: hundreds of millions moved in four decades. The hukou household-registration system still shapes who counts as urban.\n\nThis record contains aggregate statistics only.", "facts": ["63.89% urban in 2020.", "~902M city dwellers.", "Largest migration in history."]}, {"title": "Lagos — Africa's megacity, ~15 million", "brief": "Lagos holds an estimated 15 million people — Africa's largest city, growing toward 20 million, built across lagoons and islands.", "genre": "urbanization", "text": "URBAN ANALYSIS — LAGOS, NIGERIA\nSource: UN WUP 2018; Lagos Bureau of Statistics (public aggregate statistics).\n\n- Metro estimate: ~15,000,000\n- 1950 population: ~325,000\n- Density: among the world's highest for a metro\n- State claim (2012): 21M (disputed; UN uses ~15M)\n\nLagos grows by an estimated 600,000+ people per year — one of the fastest-growing megacities on Earth.\n\nThis record contains aggregate statistics only.", "facts": ["Metro: ~15M.", "From 325K in 1950.", "+600K per year."]}, {"title": "US 2020: 86% metropolitan", "brief": "86% of Americans lived in metropolitan areas in 2020. The New York metro alone (20.1M) exceeds most states.", "genre": "urbanization", "text": "URBAN ANALYSIS — UNITED STATES, 2020\nSource: US Census Bureau (public aggregate statistics).\n\n- Metropolitan population: 86%\n- New York-Newark-Jersey City metro: 20,140,470\n- Los Angeles metro: 13,200,998\n- Fastest-growing large metro 2010–2020: Austin (+33%)\n\nThe Census Bureau defines 384 metropolitan statistical areas; the top 10 hold over a quarter of all Americans.\n\nThis record contains aggregate statistics only.", "facts": ["86% metropolitan.", "NYC metro: 20.1M.", "Austin grew 33%."]}, {"title": "São Paulo — South America's giant, ~22 million", "brief": "Greater São Paulo's ~22 million people make it the Southern Hemisphere's largest city — an industrial colossus built on coffee wealth.", "genre": "urbanization", "text": "URBAN ANALYSIS — SÃO PAULO\nSource: IBGE; UN WUP 2018 (public aggregate statistics).\n\n- Metro: ~22,000,000\n- Municipality (2022): 11,451,245\n- 1872 population: 31,385\n- Helicopter fleet: one of the world's largest (traffic response)\n\nSão Paulo grew from a Jesuit mission village (1554) to a 22-million metro on coffee, industry, and immigration.\n\nThis record contains aggregate statistics only.", "facts": ["Metro: ~22M.", "From 31K in 1872.", "Southern Hemisphere's largest."]}, {"title": "Cairo — the Arab world's largest city", "brief": "Greater Cairo holds ~21 million people — the largest metro in the Arab world and Africa, layered over 1,000 years of capitals.", "genre": "urbanization", "text": "URBAN ANALYSIS — CAIRO\nSource: CAPMAS; UN WUP 2018 (public aggregate statistics).\n\n- Metro: ~21,000,000\n- 2017 census (governorate): 9,539,673\n- Founded: 969 CE (al-Qahira); settlement far older\n- New Administrative Capital under construction east of the city\n\nCairo's metro spans Fatimid, Mamluk, Ottoman, and modern layers — 'the city of a thousand minarets'.\n\nThis record contains aggregate statistics only.", "facts": ["Metro: ~21M.", "Founded 969 CE.", "Largest Arab-world city."]}, {"title": "Mumbai — 20 million on seven islands", "brief": "Mumbai's ~20 million people live on seven merged islands at 20,000+ per sq km — India's financial capital and densest great city.", "genre": "urbanization", "text": "URBAN ANALYSIS — MUMBAI\nSource: Census of India 2011; UN WUP 2018 (public aggregate statistics).\n\n- Metro: ~20,000,000\n- Municipality (2011): 12,442,373\n- Density: ~20,000 per sq km (among the world's highest)\n- Dharavi: among Asia's largest informal settlements\n\nMumbai handles ~70% of India's maritime trade and hosts its film and finance industries.\n\nThis record contains aggregate statistics only.", "facts": ["Metro: ~20M.", "Density ~20K per sq km.", "70% of maritime trade."]}, {"title": "International migrants: 281 million, 2020", "brief": "The UN counted 281 million international migrants in 2020 — 3.6% of humanity, more than the population of all but four countries.", "genre": "migration", "text": "MIGRATION ANALYSIS — WORLD, 2020\nSource: UN DESA International Migrant Stock 2020 (public aggregate statistics).\n\n- International migrants: 281,000,000 (3.6% of world population)\n- 1990: 153M; 2000: 174M; 2010: 221M\n- Top destination: United States (50.6M)\n- Top origin: India (17.9M abroad)\n- Refugees: ~34M (UNHCR)\n\nNearly two-thirds of migrants live in high-income countries; labor migration dominates the flows.\n\nThis record contains aggregate statistics only.", "facts": ["281M migrants (3.6%).", "Top destination: USA (50.6M).", "Top origin: India (17.9M)."]}, {"title": "US foreign-born: 45.3 million, 2021", "brief": "The American Community Survey put the US foreign-born at 45.3 million in 2021 — 13.6% of the population, near the historic 1890 peak share.", "genre": "migration", "text": "MIGRATION ANALYSIS — UNITED STATES\nSource: US Census Bureau, American Community Survey 2021 (public aggregate statistics).\n\n- Foreign-born: 45,300,000 (13.6%)\n- Historic peak share: 14.8% (1890)\n- Largest origin: Mexico (~10.7M)\n- California: 10.5M foreign-born (largest state count)\n\nThe 2021 share approaches the 1890 record, driven by Latin American and Asian immigration.\n\nThis record contains aggregate statistics only.", "facts": ["45.3M foreign-born.", "13.6% of population.", "Near 1890 record share."]}, {"title": "India's diaspora: 17.9 million abroad", "brief": "India has the world's largest diaspora: 17.9 million Indians live abroad — in the Gulf, the US, the UK, and beyond.", "genre": "migration", "text": "MIGRATION ANALYSIS — INDIAN DIASPORA\nSource: UN DESA 2020 (public aggregate statistics).\n\n- Indians abroad: 17,900,000 (world's largest diaspora)\n- UAE: ~3.5M; Saudi Arabia: ~2.5M; United States: ~2.7M\n- Remittances to India: ~$111B (2022, world #1 recipient)\n\nRemittances exceed 3% of India's GDP — the single largest flow to any country.\n\nThis record contains aggregate statistics only.", "facts": ["17.9M abroad (world #1).", "Remittances: ~$111B (2022).", "UAE, Saudi, US top hosts."]}, {"title": "Syrian displacement: 6.8 million refugees", "brief": "UNHCR counts 6.8 million Syrian refugees — the largest refugee population of the 2020s — hosted mainly in Turkey, Lebanon, and Jordan.", "genre": "migration", "text": "MIGRATION ANALYSIS — SYRIAN REFUGEES\nSource: UNHCR 2023 (public aggregate statistics).\n\n- Syrian refugees: ~6,800,000\n- Turkey: ~3.4M (largest host)\n- Lebanon: ~800,000 (highest per capita: ~1 in 6 residents)\n- Internally displaced: ~6.8M more inside Syria\n\nThe Syrian crisis is the largest displacement of the 21st century so far.\n\nThis record contains aggregate statistics only.", "facts": ["6.8M refugees.", "Turkey hosts 3.4M.", "Lebanon: 1 in 6 residents."]}, {"title": "Gulf migration: Qatar 88% migrant", "brief": "Qatar's population is ~88% international migrant — the highest share on Earth — drawn by construction and energy work.", "genre": "migration", "text": "MIGRATION ANALYSIS — GULF STATES\nSource: UN DESA 2020 (public aggregate statistics).\n\nMigrant share of population:\n- Qatar: ~88%\n- UAE: ~87%\n- Kuwait: ~72%\n- Bahrain: ~55%\n\nThe kafala sponsorship system historically tied workers to employers; Qatar and others have reformed it since 2020. Indians, Bangladeshis, Pakistanis, Filipinos, and Egyptians dominate the flows.\n\nThis record contains aggregate statistics only.", "facts": ["Qatar: ~88% migrant.", "UAE: ~87%.", "Kafala reforms since 2020."]}, {"title": "Venezuelan exodus: 7.7 million", "brief": "7.7 million Venezuelans have left since 2014 — one of the largest displacements in the Western Hemisphere's history — mostly to Colombia and Peru.", "genre": "migration", "text": "MIGRATION ANALYSIS — VENEZUELAN DISPLACEMENT\nSource: UNHCR/IOM R4V 2023 (public aggregate statistics).\n\n- Venezuelans abroad: ~7,700,000\n- Colombia: ~2.9M (largest host)\n- Peru: ~1.5M\n- Share of Venezuela's population: ~1 in 4\n\nDriven by economic collapse and political crisis since 2014.\n\nThis record contains aggregate statistics only.", "facts": ["7.7M abroad since 2014.", "Colombia hosts 2.9M.", "~1 in 4 Venezuelans."]}, {"title": "EU migration: Germany hosts 15.8 million", "brief": "Germany hosts 15.8 million international migrants — Europe's largest migrant population — including 1.2M+ refugees admitted since 2015.", "genre": "migration", "text": "MIGRATION ANALYSIS — EUROPE\nSource: UN DESA 2020; Eurostat (public aggregate statistics).\n\n- Germany: 15,800,000 migrants (19% of population)\n- United Kingdom: 9,400,000\n- France: 8,500,000\n- Spain: 6,800,000\n\nThe 2015–16 asylum surge brought over a million refugees to Germany, mostly Syrians, Afghans, and Iraqis.\n\nThis record contains aggregate statistics only.", "facts": ["Germany: 15.8M.", "UK: 9.4M; France: 8.5M.", "2015–16 asylum surge."]}, {"title": "China's floating population: 376 million", "brief": "China's 2020 census counted 376 million internal migrants — the 'floating population' — the largest internal migration on Earth.", "genre": "migration", "text": "MIGRATION ANALYSIS — CHINA INTERNAL\nSource: National Bureau of Statistics of China, 2020 census (public aggregate statistics).\n\n- Floating population: 375,816,759\n- Share of population: 26.6%\n- Guangdong: largest inflow province (~52M migrants)\n\nRural-to-urban workers power the coastal factories; the hukou system still limits their access to urban schooling and healthcare.\n\nThis record contains aggregate statistics only.", "facts": ["376M internal migrants.", "26.6% of population.", "Largest internal migration."]}, {"title": "Australia: 30% born overseas", "brief": "Australia's 2021 census found 27.6% born overseas — among the highest shares in the world — with England, India, and China top origins.", "genre": "migration", "text": "MIGRATION ANALYSIS — AUSTRALIA, 2021\nSource: Australian Bureau of Statistics, 2021 Census (public aggregate statistics).\n\n- Born overseas: 27.6%\n- England: 927,490 (top birthplace)\n- India: 673,352\n- China: 549,270\n- Sydney: 40%+ overseas-born\n\nPost-war migration transformed Australia from ~90% British-origin (1947) to one of the world's most diverse nations.\n\nThis record contains aggregate statistics only.", "facts": ["27.6% born overseas.", "England, India, China top.", "Sydney 40%+ overseas-born."]}, {"title": "Remittances: $831 billion, 2022", "brief": "Migrants sent $831 billion home in 2022 — triple development aid — with India ($111B) the top recipient.", "genre": "migration", "text": "MIGRATION ANALYSIS — REMITTANCES, 2022\nSource: World Bank/KNOMAD 2023 (public aggregate statistics).\n\n- Global remittances: $831,000,000,000\n- Top recipients: India ($111B), Mexico ($61B), China ($51B), Philippines ($38B)\n- Remittances vs. official aid: ~3:1\n- Tajikistan: remittances ~51% of GDP (highest share)\n\nRemittances are the largest external finance flow to low- and middle-income countries.\n\nThis record contains aggregate statistics only.", "facts": ["$831B in 2022.", "India: $111B (top).", "3x official development aid."]}, {"title": "De facto vs de jure: who counts where", "brief": "Censuses count people two ways: de facto (where you slept on census night) or de jure (where you usually live). The choice moves millions.", "genre": "methodology", "text": "METHODOLOGY GUIDE — CENSUS CONCEPTS\nPublic knowledge explainer (aggregate concepts only).\n\n- De facto: count people where they are found on census night (used by e.g. India historically).\n- De jure: count people at their usual residence (used by e.g. the United States).\n- The US 'usual residence' rule is why college students count at school and prisoners at prison — both contested.\n- Tourists, diplomats, and the homeless are treated differently by each method.\n- The UN recommends the 'usual residence' (12-month) criterion for international comparability.\n\nThis record explains public methodology. No individual data.", "facts": ["De facto: where you slept.", "De jure: usual residence.", "UN recommends 12-month rule."]}, {"title": "Post-enumeration surveys: measuring the undercount", "brief": "Every census misses people. Post-enumeration surveys re-interview samples to estimate the net undercount — the US 2020 undercounted Hispanics by ~5%.", "genre": "methodology", "text": "METHODOLOGY GUIDE — COVERAGE MEASUREMENT\nPublic knowledge explainer (aggregate concepts only).\n\n- The US 2020 Post-Enumeration Survey found a net undercount of 5.0% for Hispanics, 3.3% for Black Americans, and an overcount of 1.6% for non-Hispanic whites.\n- Method: dual-system (capture-recapture) estimation — compare census to an independent survey.\n- The UK, Australia, and Canada run similar coverage surveys.\n- Undercounts skew funding and representation: the US census guides $1.5T+ in federal funds.\n\nThis record explains public methodology. No individual data.", "facts": ["Dual-system estimation.", "US 2020: -5.0% Hispanic.", "Guides $1.5T+ in funds."]}, {"title": "Register-based censuses: the Nordic model", "brief": "Denmark, Finland, Norway, and Sweden run censuses from population registers — no forms, no enumerators — updated continuously from administrative records.", "genre": "methodology", "text": "METHODOLOGY GUIDE — REGISTER CENSUSES\nPublic knowledge explainer (aggregate concepts only).\n\n- Denmark ran the first fully register-based census in 1981.\n- Sources linked: population register, tax, education, employment, housing registers.\n- Advantages: annual (even monthly) statistics, lower cost, no respondent burden.\n- Requirement: a universal personal ID number and high-trust administration.\n- The Netherlands, Belgium, and Austria use combined register + survey models.\n\nThis record explains public methodology. No individual data.", "facts": ["Denmark first: 1981.", "Needs universal ID + trust.", "Annual statistics possible."]}, {"title": "The UN Principles and Recommendations", "brief": "The UN's Principles and Recommendations for Population and Housing Censuses set the global standard: universality, simultaneity, defined periodicity.", "genre": "methodology", "text": "METHODOLOGY GUIDE — UN STANDARDS\nPublic knowledge explainer (aggregate concepts only).\n\nThe UN Statistics Division's core principles:\n1. Individual enumeration — separate records per person (aggregated for release)\n2. Universality — everyone in the territory\n3. Simultaneity — a single reference moment\n4. Defined periodicity — at least every 10 years\n5. Small-area statistics — data for local planning\n\nThe 2020 census round (2015–2024) saw 150+ countries enumerate, most within the decade.\n\nThis record explains public methodology. No individual data.", "facts": ["5 core principles.", "150+ countries in 2020 round.", "Decennial minimum."]}, {"title": "Disclosure control: how censuses protect privacy", "brief": "Census bureaus perturb tables to protect respondents: cell suppression, rounding, swapping — and now differential privacy in the US 2020 release.", "genre": "methodology", "text": "METHODOLOGY GUIDE — STATISTICAL DISCLOSURE CONTROL\nPublic knowledge explainer (aggregate concepts only).\n\n- Cell suppression: hide small cells (the UK's classic method).\n- Rounding: round counts to base 3 or 5.\n- Record swapping: exchange similar households between areas.\n- Differential privacy: the US 2020 census injected calibrated noise into published tables — controversial with researchers.\n- Principle: publish aggregates; never release identifiable individual records.\n\nModern censuses keep individual forms sealed for decades (72 years in the US; 100 in the UK).\n\nThis record explains public methodology. No individual data.", "facts": ["Suppression, rounding, swapping.", "US 2020: differential privacy.", "Forms sealed 72–100 years."]}, {"title": "Census intervals: why ten years", "brief": "The ten-year census cycle comes from the US Constitution (1790) and British practice (1801) — long enough for change, short enough to stay relevant.", "genre": "methodology", "text": "METHODOLOGY GUIDE — PERIODICITY\nPublic knowledge explainer (aggregate concepts only).\n\n- US: every 10 years, constitutionally required (Article I).\n- UK: every 10 years since 1801 (except 1941, wartime).\n- Japan: every 5 years (large-scale every 10).\n- France: rolling census — a sample each year, full refresh every 5.\n- Germany: register-based with a 10-year full census (2011, 2022).\n\nThe UN recommends at least decennial censuses; war, cost, and politics cause the gaps.\n\nThis record explains public methodology. No individual data.", "facts": ["US/UK: decennial.", "Japan: every 5 years.", "France: rolling sample."]}, {"title": "The 2020 round goes digital", "brief": "The 2020 census round was the first digital one: online self-response in the US, UK, and Australia; handheld devices for enumerators worldwide.", "genre": "methodology", "text": "METHODOLOGY GUIDE — DIGITAL CENSUSES\nPublic knowledge explainer (aggregate concepts only).\n\n- US 2020: first census with internet self-response as the primary mode.\n- UK 2021: 'digital-first' — 88%+ responded online.\n- Australia 2021: online-first; the 2016 site crash led to a rebuilt system.\n- Pakistan 2023: South Asia's first fully digital census (tablets, GPS).\n- Geospatial: satellite imagery now guides enumeration-area mapping in Africa.\n\nDigital collection cut costs but raised cyber and inclusion risks.\n\nThis record explains public methodology. No individual data.", "facts": ["US/UK/Australia: online-first.", "Pakistan 2023: tablets + GPS.", "Satellite mapping in Africa."]}, {"title": "Censuses and money: $1.5 trillion rides on the count", "brief": "The US census guides $1.5T+ in annual federal funding — Medicaid, highways, schools. An undercounted person costs their community thousands.", "genre": "methodology", "text": "METHODOLOGY GUIDE — CENSUS USES\nPublic knowledge explainer (aggregate concepts only).\n\n- US: 300+ federal programs use census data; ~$1.5T/year distributed.\n- Apportionment: 435 House seats reallocated after each census.\n- Business: site selection, market sizing, logistics planning.\n- Research: the denominator for nearly every rate — disease, crime, poverty.\n- George Washington University estimated each uncounted person costs a state ~$1,000–$2,000/year in lost funds.\n\nThis record explains public methodology. No individual data.", "facts": ["$1.5T/year guided.", "435 House seats.", "Each miss costs $1–2K/year."]}, {"title": "Historical census substitutes: tax rolls and parish registers", "brief": "Before modern censuses, historians use hearth taxes, parish registers, and muster rolls — the raw material of historical demography.", "genre": "methodology", "text": "METHODOLOGY GUIDE — PRE-CENSUS SOURCES\nPublic knowledge explainer (aggregate concepts only).\n\n- Hearth taxes (e.g., England 1662–1689): count fireplaces as a household proxy.\n- Parish registers: baptisms, marriages, burials from the 1500s — family reconstitution.\n- The Cambridge Group (Wrigley & Schofield) rebuilt England's population 1541–1871 from 404 parishes.\n- Ottoman tahrir defters: detailed 15th–16th century tax surveys.\n- Japanese shūmon aratame-chō: religious inquisition registers doubling as population records.\n\nHistorical demography reconstructs populations without a single census form.\n\nThis record explains public methodology. No individual data.", "facts": ["Hearth tax = household proxy.", "Cambridge Group: 404 parishes.", "Ottoman tahrir defters."]}, {"title": "Why some countries skip the census", "brief": "Lebanon hasn't held a census since 1932; Somalia and DR Congo for decades. War, cost, and political sensitivity keep dozens of countries uncounted.", "genre": "methodology", "text": "METHODOLOGY GUIDE — CENSUS GAPS\nPublic knowledge explainer (aggregate concepts only).\n\n- Lebanon: last census 1932 — sectarian power-sharing depends on not recounting.\n- Somalia: no full census since 1975.\n- DR Congo: no full census since 1984.\n- Afghanistan: none since 1979.\n- Cost: a full census runs $1–$10+ per person — prohibitive for poor states.\n- Alternatives: UN estimates, surveys (DHS, MICS), satellite + mobile data models.\n\nGaps are filled by demographic modeling — less precise, but the only option.\n\nThis record explains public methodology. No individual data.", "facts": ["Lebanon: 1932 (last).", "DR Congo: 1984.", "Cost: $1–10+ per person."]}];
function buildContent(t){
  return {summary:t.brief, full_text:t.text, key_facts:t.facts||[]};
}
function defaultDemo(){
  return{kind:'record-program',
    program:"// record card — run with: node demo.js\n// (place the record JSON next to this file as record.json)\nconst card = JSON.parse(require('fs').readFileSync('record.json', 'utf8'));\nconsole.log(card.id + ' — ' + card.title + ' [' + card.src + ']');\nconsole.log('Illustration: ' + card.illustration);",
    note:'A runnable program card for this record. Save as demo.js, save the record JSON as record.json beside it, and run with node.'};
}
function generate(seed,opts){
  opts=opts||{};
  var s=(seed>>>0)||1;
  var pool=TOPICS, ti=(s-1)%TOPICS.length;
  if(opts.genre&&GENRES.indexOf(opts.genre)>=0){
    pool=TOPICS.filter(function(t){return t.genre===opts.genre;});
    if(pool.length) ti=(s-1)%pool.length; else {pool=TOPICS;ti=(s-1)%TOPICS.length;}
  }
  var t=pool[ti];
  var ctopic=opts.topic?String(opts.topic).trim().slice(0,120):'';
  var title=t.title, brief=t.brief, text=t.text;
  if(ctopic){title=ctopic+' — a '+RECORD_KIND;brief='A user-requested '+RECORD_KIND+' on "'+ctopic+'".';text='User-requested topic: '+ctopic+'. '+t.text;}
  var id=PREFIX+pad(s);
  var rec={id:id,title:title,description:brief+' Full material below.',genre:t.genre,type:RECORD_KIND,
    content:buildContent({brief:brief,text:text,facts:t.facts||[]}),
    illustration:'media/illus-'+String(s).padStart(4,'0')+'.svg',
    demo:defaultDemo(),src:SRC,_seed:s};

  return rec;
}
function validate(r){
  var e=[];
  if(!r||typeof r!=='object')return{ok:false,errors:['not an object']};
  if(typeof r.id!=='string'||r.id.indexOf(PREFIX)!==0||!/\d{6}$/.test(r.id))e.push('id');
  if(typeof r.title!=='string'||r.title.length<6)e.push('title');
  if(typeof r.description!=='string'||r.description.length<30)e.push('description');
  if(GENRES.indexOf(r.genre)<0)e.push('genre');
  if(!r.content||typeof r.content!=='object'||typeof r.content.full_text!=='string'||r.content.full_text.length<80)e.push('content');
  if(!r.demo||typeof r.demo!=='object')e.push('demo');
  return{ok:!e.length,errors:e};
}
function driftCheck(rec,sample){
  for(var i=0;i<sample.length;i++){if(sample[i]&&sample[i].t===rec.title)return{ok:false,errors:['duplicate title in archive sample']};}
  return{ok:true,errors:[]};
}
var gen={version:'jahdb-census-records-public-generator-1.0',generate:generate,validate:validate,driftCheck:driftCheck,genres:GENRES};
if(typeof JAHDB!=='undefined'&&JAHDB.registerGenerator)JAHDB.registerGenerator('census-records-public',gen);
if(typeof module!=='undefined'&&module.exports)module.exports=gen;
})();
